import React, { useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import Sidebar from '../components/Sidebar';
import { IoLocationOutline, IoCalendarOutline, IoTimeOutline, IoStar, IoCheckmarkCircleOutline } from 'react-icons/io5';
import '../CardDetails.css';

const CardDetails = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { travelData } = location.state || {};

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  if (!travelData) {
    return (
      <div className="no-data-error">
        <h2>Oops! No data found.</h2>
        <button onClick={() => navigate('/')}>Back to Home</button>
      </div>
    );
  }

  const renderStars = (rating) => {
    return [...Array(5)].map((_, i) => (
      <IoStar
        key={i}
        color={i < Math.round(rating) ? "#d4a373" : "#e0e0e0"}
        size={18}
      />
    ));
  };

  return (
    <main className="card-details-page">
      <Navbar defaultSticky />

      <div className="article-hero" style={{ backgroundImage: `url(${travelData.img})` }}>
        <div className="article-hero-overlay">
          <div className="article-hero-content">
            <span className="article-category">{travelData.category}</span>
            <h1 className="article-title">{travelData.title}</h1>
            <div className="article-meta-wide">
              <div className="meta-item">
                <IoLocationOutline />
                <a href={travelData.googleMapsUrl} target="_blank" rel="noopener noreferrer">
                  {travelData.location}
                </a>
              </div>
              <div className="meta-item">
                <IoCalendarOutline />
                <span>{travelData.startDate}</span>
              </div>
              <div className="meta-item">
                <IoTimeOutline />
                <span>{travelData.readTime}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="card-details-container">
        <div className="blog-post-content">
          <div className="article-header">
            <div className="rating-row">
              {renderStars(travelData.rating)}
              <span className="rating-val">{travelData.rating} / 5</span>
            </div>
          </div>

          <div className="highlights-box">
            <h3>Trip Highlights</h3>
            <ul>
              {travelData.highlights && travelData.highlights.map((h, i) => (
                <li key={i}>
                  <IoCheckmarkCircleOutline />
                  <span>{h}</span>
                </li>
              ))}
            </ul>
          </div>

          <p className="article-body">
            {travelData.description}
          </p>

          <div className="tags-container">
            {travelData.tags && travelData.tags.map(tag => (
              <span key={tag} className="tag-pill">#{tag}</span>
            ))}
          </div>
        </div>

        <Sidebar travelId={travelData.id} />
      </div>
    </main>
  );
};

export default CardDetails;
